const agora = $now.setZone('America/Sao_Paulo');
const anoInicio = agora.month >= 8 ? agora.year : agora.year - 1;

return [{
  json: {
    dataInicioPeriodo: `${anoInicio}-08-01`,
    hoje: agora.toFormat('yyyy-MM-dd')
  }
}];

const extrairLinhas = (payload) => {
  if (Array.isArray(payload.recordset)) {
    return payload.recordset;
  }

  if (Array.isArray(payload.recordsets?.[0])) {
    return payload.recordsets[0];
  }

  if (payload.IdPaciente != null || payload.idPaciente != null) {
    return [payload];
  }

  return [];
};

const linhas = [];

for (const item of items) {
  linhas.push(...extrairLinhas(item.json ?? {}));
}

const vistos = new Set();
const candidatos = [];

for (const linha of linhas) {
  const idPaciente = Number(linha.IdPaciente ?? linha.idPaciente);

  if (!Number.isFinite(idPaciente) || vistos.has(idPaciente)) {
    continue;
  }

  vistos.add(idPaciente);

  const dataFim = String(linha.DataFimBloqueio ?? linha.dataFimBloqueio ?? '').slice(0, 10);

  candidatos.push({
    json: {
      acao: 'DESBLOQUEAR',
      ativo: true,
      idPaciente,
      nomePaciente: linha.NomePaciente ?? linha.nomePaciente ?? null,
      numeroFalta: Number(linha.NumeroFalta ?? linha.numeroFalta ?? 0),
      diasBloqueio: Number(linha.DiasBloqueio ?? linha.diasBloqueio ?? 0),
      dataInicioBloqueio: linha.DataFalta ?? linha.dataFalta ?? null,
      dataFimBloqueio: dataFim || null,
      idAgenda: linha.IdAgenda ?? linha.idAgenda ?? null
    }
  });
}

if (!candidatos.length) {
  return [{ json: { semLiberacao: true } }];
}

return candidatos;

const origens = $('montar candidatos').all().filter((item) => !item.json.semLiberacao);
const pacientes = $input.all();
const liberar = [];

for (let indice = 0; indice < origens.length; indice += 1) {
  const origem = origens[indice]?.json ?? {};
  const paciente = pacientes[indice]?.json ?? {};

  if (paciente.error || paciente.message || paciente.id == null) {
    continue;
  }

  if (paciente.ativo !== false) {
    continue;
  }

  liberar.push({
    json: {
      ...origem,
      ativo: true,
      ativoCnn: paciente.ativo,
      mensagem: `Liberar paciente ${origem.nomePaciente ?? origem.idPaciente} (prazo ${origem.dataFimBloqueio} ja passou).`
    }
  });
}

return liberar;
